:root {
  --card-bg: #faf6ee;
  --card-border: #b89a5e;
  --header-bg: #2b1d0e;
  --header-text: #f0d89a;
  --accent-gold: #c9a84c;
  --accent-light: #f0d89a;
  --body-text: #2b1d0e;
  --muted-text: #7a5c2e;
  --divider: #d4b97a;
  --white-badge-bg: #ffffff;
  --white-badge-border: #b89a5e;
  --badge-bg: #2b1d0e;
  --badge-text: #f0d89a;
  --footer-bg: #f0e4c3;
}

.chess-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 10px;
  width: 440px;
  overflow: hidden;
  font-size: 14px;
  color: var(--body-text);
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
}

.tourney-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--header-text);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.card-year {
  font-size: 13px;
  font-weight: 600;
  color: var(--accent-gold);
  letter-spacing: 0.05em;
}

.card-body {
  padding: 16px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.player-info {
  display: flex;
  align-items: center;
  gap: 14px;
}

.player-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background-color: var(--header-bg);
  color: var(--accent-light);
  font-size: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--accent-gold);
  flex-shrink: 0;
}

.player-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.player-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--body-text);
  margin: 0;
  line-height: 1.2;
}

.player-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--muted-text);
  margin: 0;
  letter-spacing: 0.03em;
}

.divider {
  height: 1px;
  background-color: var(--divider);
  border-radius: 1px;
}

.match-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex: 1;
}

.meta-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted-text);
}

.meta-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--body-text);
}

.color-badge {
  font-size: 12px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  border: 1.5px solid var(--white-badge-border);
  background-color: var(--white-badge-bg);
  color: var(--body-text);
}

.card-footer {
  background-color: var(--footer-bg);
  border-top: 1.5px solid var(--divider);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
}

.footer-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.venue {
  font-size: 13px;
  font-weight: 600;
  color: var(--body-text);
}

.date {
  font-size: 11px;
  color: var(--muted-text);
  font-weight: 500;
}

.rating-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  border-radius: 6px;
  padding: 6px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.rating-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
}

.rating-num {
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  color: var(--badge-text);
}
